// ============================================================================
// 1. COORDENADAS DAS ZONAS E SNAP POINTS
// ============================================================================

type Vetor3 = [number, number, number];
type FaseJogo = "FASE_1" | "FASE_2" | "FASE_3" | "FASE_4" | "FASE_5" | "FIM_DE_JOGO";

interface ConfigJogador {
  nome: string;
  nomeSnapAtaque: string;
  pontoAtaque: Vetor3;
}

interface ResultadoPontuacao {
  pontos: number;
  percentual: number;
  passosDebug: string[];
}

const POSICOES_BASE: Record<string, Vetor3> = {
  Ocorrencia_1: [-0.315, 1.52, 0.181],
  Ocorrencia_2: [0, 1.515, 0.178],
  Ocorrencia_3: [0.308, 1.529, 0.179],
  Deposito_1: [-0.311, 1.522, -0.153],
  Deposito_2: [0, 1.513, -0.157],
  Deposito_3: [0.306, 1.534, -0.147],
  Zona_Descarte: [0.949, 1.536, 0.093],
};

const POSICOES_MESA: Record<string, Vetor3> = { ...POSICOES_BASE };

const ALTURA_MESA = 1.515;
const RAIO_DETECCAO = 0.16;

// Configuração simplificada (a engine cuida das mãos nativamente agora)
const JOGADORES_MESA: ConfigJogador[] = [
  { nome: "Jogador 1", nomeSnapAtaque: "Ataque_1", pontoAtaque: [0, ALTURA_MESA, 0.43] },
  { nome: "Jogador 2", nomeSnapAtaque: "Ataque_2", pontoAtaque: [-1.43, ALTURA_MESA, 0.33] },
  { nome: "Jogador 3", nomeSnapAtaque: "Ataque_3", pontoAtaque: [-2.43, ALTURA_MESA, 0.33] },
];

// ============================================================================
// 2. ESTADO DO JOGO
// ============================================================================

interface EstadoJogo {
  jogoIniciado: boolean;
  rodada: number;
  faseAtual: FaseJogo;
  pontuacaoOculta: number;
  cartasAtaqueDaRodada: Set<string>;
  deckAcaoFaceUpBase: boolean;
  ultimoTotalSnapsPreenchidos: number;
  posicoesAnteriores: Map<string, Vetor3>;
  ocupado: boolean;
}

const estado: EstadoJogo = {
  jogoIniciado: false,
  rodada: 1,
  faseAtual: "FASE_1",
  pontuacaoOculta: 0,
  cartasAtaqueDaRodada: new Set<string>(),
  deckAcaoFaceUpBase: false,
  ultimoTotalSnapsPreenchidos: 0,
  posicoesAnteriores: new Map<string, Vetor3>(),
  ocupado: false,
};

// ============================================================================
// 3. FUNÇÕES UTILITÁRIAS
// ============================================================================

function lerVetor(pos: any, yFallback = ALTURA_MESA): Vetor3 {
  if (Array.isArray(pos)) return [Number(pos[0] ?? 0), Number(pos[1] ?? yFallback), Number(pos[2] ?? 0)];
  if (pos && typeof pos === "object") return [Number(pos.x ?? 0), Number(pos.y ?? yFallback), Number(pos.z ?? 0)];
  return [0, yFallback, 0];
}

async function pausaFisica(segundos = 0.06): Promise<boolean> {
  const w = world as any;
  if (typeof w.wait === "function") {
    await w.wait(segundos);
    return true;
  }
  const timer = (globalThis as any).setTimeout;
  if (typeof timer === "function") {
    await new Promise<void>((resolve) => timer(resolve, Math.max(15, Math.round(segundos * 1000))));
    return true;
  }
  return false;
}

function encontrarSnapDisponivel(snapPoints: any[], usados: Set<any>, coordenadaBase: Vetor3, nomeOpcional?: string): any | null {
  if (nomeOpcional) {
    const porNome = snapPoints.find((sp: any) => !usados.has(sp) && String(sp?.name ?? "").trim().toLowerCase() === nomeOpcional.toLowerCase());
    if (porNome) return porNome;
  }
  let maisProximo: any = null;
  let menorDist = 0.3;
  for (const sp of snapPoints) {
    if (usados.has(sp)) continue;
    const [sx, , sz] = lerVetor(sp.position ?? sp);
    const dist = Math.hypot(sx - coordenadaBase[0], sz - coordenadaBase[2]);
    if (dist < menorDist) {
      menorDist = dist;
      maisProximo = sp;
    }
  }
  return maisProximo;
}

async function sincronizarComSnapPoints() {
  const snapPoints: any[] = (await world.getSnapPoints?.()) ?? [];
  const usados = new Set<any>();

  for (const chave of Object.keys(POSICOES_BASE)) {
    const sp = encontrarSnapDisponivel(snapPoints, usados, POSICOES_BASE[chave], chave);
    if (sp) {
      usados.add(sp);
      POSICOES_MESA[chave] = lerVetor(sp.position ?? sp);
    }
  }

  for (const jogador of JOGADORES_MESA) {
    const spAtaque = encontrarSnapDisponivel(snapPoints, usados, jogador.pontoAtaque, jogador.nomeSnapAtaque);
    if (spAtaque) {
      usados.add(spAtaque);
      jogador.pontoAtaque = lerVetor(spAtaque.position ?? spAtaque);
    }
  }
}

async function listarTodosObjetos(): Promise<any[]> {
  const objetos: any[] = await world.getAllObjects();
  return objetos ?? [];
}

async function obterObjetoPorNome(nome: string): Promise<any> {
  const todos = await listarTodosObjetos();
  return todos.find((obj: any) => obj?.name === nome) ?? null;
}

function dentroDaArea(posObj: any, centro: Vetor3, raioX = RAIO_DETECCAO, raioZ = RAIO_DETECCAO): boolean {
  const [ox, , oz] = lerVetor(posObj);
  const [cx, , cz] = centro;
  return Math.abs(ox - cx) <= raioX && Math.abs(oz - cz) <= raioZ;
}

function estaCartaAssentada(obj: any, centro: Vetor3): boolean {
  if (!obj || obj.isHeld || obj.heldBy || obj.grabbedBy || obj.isDragging) return false;
  const [ox, oy, oz] = lerVetor(obj.position);
  if (oy > Math.max(centro[1], ALTURA_MESA) + 0.08) return false;
  const chaveId = String(obj.id ?? "");
  if (chaveId) {
    const posAnt = estado.posicoesAnteriores.get(chaveId);
    if (!posAnt || Math.hypot(ox - posAnt[0], oy - posAnt[1], oz - posAnt[2]) > 0.008) return false;
  }
  return true;
}

function atualizarHistoricoPosicoes(objetos: any[]) {
  const proximoMapa = new Map<string, Vetor3>();
  for (const obj of objetos) {
    if (obj?.id) proximoMapa.set(String(obj.id), lerVetor(obj.position));
  }
  estado.posicoesAnteriores = proximoMapa;
}

async function objetosNaArea(centro: Vetor3, raioX = RAIO_DETECCAO, raioZ = RAIO_DETECCAO, apenasAssentadas = false): Promise<any[]> {
  const todos = await listarTodosObjetos();
  return todos.filter((obj: any) =>
    obj && obj.name !== "Deck_Ocorrencia" && obj.name !== "Deck_Acao" && String(obj.kind ?? "").toLowerCase() !== "zone" &&
    dentroDaArea(obj.position, centro, raioX, raioZ) && (!apenasAssentadas || estaCartaAssentada(obj, centro))
  );
}

async function cartasNaArea(centro: Vetor3, raioX = RAIO_DETECCAO, raioZ = RAIO_DETECCAO, apenasAssentadas = false): Promise<any[]> {
  const objetos = await objetosNaArea(centro, raioX, raioZ, apenasAssentadas);
  return objetos.filter((obj: any) => (obj.stackCount ?? 1) <= 1);
}

function contarTotalCartas(objetos: any[]): number {
  return objetos.reduce((soma, obj) => soma + Number(obj?.stackCount ?? 1), 0);
}

async function definirTravaFisica(obj: any, travar: boolean) {
  if (!obj) return;
  try {
    if (travar && typeof obj.lock === "function") await obj.lock();
    else if (!travar && typeof obj.unlock === "function") await obj.unlock();
    else if ("locked" in obj) obj.locked = travar;
  } catch (_) {}
}

async function moverCartaParaPonto(carta: any, destino: Vetor3, viradaParaCima: boolean, rotacaoY = 0, indicePilha = 0, travarNaMesa = false) {
  if (!carta || !destino) return;
  await definirTravaFisica(carta, false);

  if (viradaParaCima && carta.faceUp === false && typeof carta.flip === "function") { await carta.flip(); await pausaFisica(0.22); } 
  else if (!viradaParaCima && carta.faceUp === true && typeof carta.flip === "function") { await carta.flip(); await pausaFisica(0.22); }

  if (typeof carta.setRotation === "function") {
    const rotAtual = Array.isArray(carta.rotation) ? carta.rotation : [0, rotacaoY, 0];
    const virouPeloEixoX = Math.abs(Number(rotAtual[0] ?? 0)) > 90;
    const rzNormalizado = virouPeloEixoX ? (Math.abs(Number(rotAtual[2] ?? 0)) > 90 ? 0 : 180) : Number(rotAtual[2] ?? 0);
    await carta.setRotation([0, rotacaoY, rzNormalizado]);
  }

  const ySeguro = Number((Math.max(destino[1], ALTURA_MESA) + indicePilha * 0.015).toFixed(3));
  if (typeof carta.setPosition === "function") await carta.setPosition([destino[0], ySeguro, destino[2]]);

  await definirTravaFisica(carta, travarNaMesa);
  if (typeof carta.refresh === "function") await carta.refresh();
  await pausaFisica(0.05);
}

async function puxarCartaDoDeck(deck: any): Promise<any | null> {
  if (!deck || (deck.stackCount ?? 0) <= 0) return null;
  let carta = typeof deck.drawCard === "function" ? await deck.drawCard() : (typeof deck.draw === "function" ? await deck.draw(1) : null);
  if (Array.isArray(carta)) carta = carta[0];
  return carta ?? null;
}

async function descompactarPilhas(objetos: any[]): Promise<any[]> {
  const individuais: any[] = [];
  for (const obj of objetos) {
    if (!obj) continue;
    await definirTravaFisica(obj, false);
    while ((obj.stackCount ?? 1) > 1) {
      const extra = await puxarCartaDoDeck(obj);
      if (!extra) break;
      individuais.push(extra);
    }
    individuais.push(obj);
  }
  return individuais;
}

// ============================================================================
// 4. FLUXO DAS FASES (LOOP DA RODADA)
// ============================================================================

async function iniciarJogo() {
  if (estado.jogoIniciado) return;
  estado.jogoIniciado = true;
  estado.rodada = 1;
  estado.pontuacaoOculta = 0;

  await sincronizarComSnapPoints();

  const deckOcorrencia = await obterObjetoPorNome("Deck_Ocorrencia");
  const deckAcao = await obterObjetoPorNome("Deck_Acao");
  if (typeof deckOcorrencia?.shuffle === "function") await deckOcorrencia.shuffle();
  if (typeof deckAcao?.shuffle === "function") await deckAcao.shuffle();
  if (deckAcao) estado.deckAcaoFaceUpBase = Boolean(deckAcao.faceUp);

  await executarFase1();
  iniciarMonitoramentoContinuo();
}

// FASE 1: Ocorrências
async function executarFase1() {
  estado.faseAtual = "FASE_1";
  const deckOcorrencia = await obterObjetoPorNome("Deck_Ocorrencia");

  for (let i = 1; i <= 3; i++) {
    const pontoOcorrencia = POSICOES_MESA[`Ocorrencia_${i}`];
    const cartasAtuais = await objetosNaArea(pontoOcorrencia, RAIO_DETECCAO, RAIO_DETECCAO, false);

    if (cartasAtuais.length === 0) {
      const novaCarta = await puxarCartaDoDeck(deckOcorrencia);
      if (novaCarta) await moverCartaParaPonto(novaCarta, pontoOcorrencia, true, 0, 0, true);
    } else {
      await definirTravaFisica(cartasAtuais[0], true);
    }
  }
  await executarFase2();
}

// FASE 2: Deal nativo direto para as mãos!
async function executarFase2() {
  estado.faseAtual = "FASE_2";
  const deckAcao = await obterObjetoPorNome("Deck_Acao");

  if (deckAcao && typeof deckAcao.deal === "function") {
    // Na rodada 1, entrega 4 cartas para todos os assentos ocupados. Nas demais, repõe 1 carta.
    const quantidadeParaComprar = estado.rodada === 1 ? 4 : 1;
    try {
      await deckAcao.deal(quantidadeParaComprar);
      await pausaFisica(0.5); // Aguarda animação de deal nativo
    } catch (_) {}
  }

  await iniciarFase3();
}

// FASE 3: Jogadores alocam 1 carta de Ataque
async function iniciarFase3() {
  estado.faseAtual = "FASE_3";
  estado.cartasAtaqueDaRodada.clear();
  estado.ultimoTotalSnapsPreenchidos = 0;
  world.broadcast(`Rodada ${estado.rodada} — Fase 3: Arraste 1 carta da sua mão para o seu Snap Point de Ataque. Quando todos os pontos estiverem preenchidos, aperte F sobre o Deck_Acao para avançar.`);
}

async function prepararCartasNosSnapPointsDeAtaque() {
  if (estado.faseAtual !== "FASE_3") return;
  let preenchidos = 0;

  for (const jogador of JOGADORES_MESA) {
    const cartas = await cartasNaArea(jogador.pontoAtaque, RAIO_DETECCAO, RAIO_DETECCAO, true);
    if (cartas.length === 1) {
      preenchidos++;
      if (cartas[0].faceUp === true && typeof cartas[0].flip === "function") {
        await cartas[0].flip();
        await pausaFisica(0.2);
      }
    }
  }

  if (preenchidos !== estado.ultimoTotalSnapsPreenchidos) {
    estado.ultimoTotalSnapsPreenchidos = preenchidos;
    if (preenchidos === 3) world.broadcast("Snap Points de Ataque: 3/3 prontos! Aperte F sobre o Deck_Acao para revelar as cartas.");
    else if (preenchidos > 0) world.broadcast(`Snap Points de Ataque preenchidos: ${preenchidos}/3.`);
  }
}

async function validarEAvancarParaFase4() {
  if (estado.faseAtual !== "FASE_3") return;
  const selecionadas: { carta: any; jogador: ConfigJogador }[] = [];
  const pendentes: string[] = [];

  for (const jogador of JOGADORES_MESA) {
    const objetos = await objetosNaArea(jogador.pontoAtaque, RAIO_DETECCAO, RAIO_DETECCAO, true);
    const total = contarTotalCartas(objetos);
    if (total === 0) { pendentes.push(`${jogador.nome} (vazio)`); continue; }
    if (total > 1) { pendentes.push(`${jogador.nome} (>1 carta)`); continue; }
    selecionadas.push({ carta: objetos[0], jogador });
  }

  if (pendentes.length > 0) {
    world.broadcast(`Não foi possível avançar para a Fase 4. Faltam: ${pendentes.join(", ")}.`);
    return;
  }

  estado.cartasAtaqueDaRodada.clear();
  for (const { carta, jogador } of selecionadas) {
    await moverCartaParaPonto(carta, jogador.pontoAtaque, true, 0, 0, false);
    if (carta.id) estado.cartasAtaqueDaRodada.add(String(carta.id));
  }
  iniciarFase4();
}

// FASE 4: Mover cartas para Depósitos
function iniciarFase4() {
  estado.faseAtual = "FASE_4";
  world.broadcast("Fase 4: Cartas reveladas! Distribua todas elas nos 3 Depósitos à frente das Ocorrências.");
}

async function verificarConclusaoFase4() {
  if (estado.faseAtual !== "FASE_4") return;
  const totalEsperado = estado.cartasAtaqueDaRodada.size;
  if (totalEsperado === 0) return;

  for (const jogador of JOGADORES_MESA) {
    if ((await objetosNaArea(jogador.pontoAtaque, RAIO_DETECCAO, RAIO_DETECCAO, false)).length > 0) return;
  }

  let totalDepositado = 0;
  for (let i = 1; i <= 3; i++) {
    totalDepositado += contarTotalCartas(await objetosNaArea(POSICOES_MESA[`Deposito_${i}`], RAIO_DETECCAO, RAIO_DETECCAO, true));
  }

  if (totalDepositado >= totalEsperado) await executarFase5();
}

// FASE 5: Pontuação e Limpeza
async function executarFase5() {
  estado.faseAtual = "FASE_5";
  let indiceVencedor = 1, maiorQtdAtaques = -1;

  for (let i = 1; i <= 3; i++) {
    const qtdCartas = contarTotalCartas(await objetosNaArea(POSICOES_MESA[`Deposito_${i}`], RAIO_DETECCAO, RAIO_DETECCAO, false));
    if (qtdCartas > maiorQtdAtaques) { maiorQtdAtaques = qtdCartas; indiceVencedor = i; }
  }

  const objOcorrencia = await objetosNaArea(POSICOES_MESA[`Ocorrencia_${indiceVencedor}`], RAIO_DETECCAO, RAIO_DETECCAO, false);
  const objAtaque = await objetosNaArea(POSICOES_MESA[`Deposito_${indiceVencedor}`], RAIO_DETECCAO, RAIO_DETECCAO, false);

  const cartasOcorrencia = await descompactarPilhas(objOcorrencia);
  const cartasAtaque = await descompactarPilhas(objAtaque);

  if (cartasOcorrencia[0]) {
    const resultado = await calcularPontuacao(cartasOcorrencia[0], cartasAtaque);
    estado.pontuacaoOculta = Number((estado.pontuacaoOculta + resultado.pontos).toFixed(2));
    // for (const linhaPasso of resultado.passosDebug) world.broadcast(`[DEBUG R${estado.rodada}] ${linhaPasso}`);
    world.broadcast(`Rodada ${estado.rodada} Concluída! Pontos ganhos: ${resultado.pontos.toFixed(2)} | Total acumulado: ${estado.pontuacaoOculta.toFixed(2)} pts`);
  }

  const pontoDescarte = POSICOES_MESA.Zona_Descarte;
  let qtdNoDescarte = contarTotalCartas(await objetosNaArea(pontoDescarte, RAIO_DETECCAO, RAIO_DETECCAO, false));

  for (const carta of cartasOcorrencia) await moverCartaParaPonto(carta, pontoDescarte, true, 0, qtdNoDescarte++, true);
  for (const carta of cartasAtaque) await moverCartaParaPonto(carta, pontoDescarte, true, 0, qtdNoDescarte++, true);

  const deckOcorrencia = await obterObjetoPorNome("Deck_Ocorrencia");
  let restamNaMesa = false;
  for (let i = 1; i <= 3; i++) {
    if ((await objetosNaArea(POSICOES_MESA[`Ocorrencia_${i}`], RAIO_DETECCAO, RAIO_DETECCAO, false)).length > 0) restamNaMesa = true;
  }

  if (((deckOcorrencia?.stackCount ?? 0) > 0) || restamNaMesa) {
    estado.rodada++;
    await executarFase1();
  } else {
    estado.faseAtual = "FIM_DE_JOGO";
    world.broadcast(`Fim de jogo! Pontuação Final: ${estado.pontuacaoOculta.toFixed(2)} pts.`);
  }
}

// ============================================================================
// 5. CÁLCULO DE PONTUAÇÃO (Mantido do seu Setup)
// ============================================================================

async function obterDadosCustomizadosDaCarta(carta: any): Promise<Record<string, any>> {
  const dadosMesclados: Record<string, any> = {};
  if (!carta || typeof carta !== "object") return dadosMesclados;

  const incorporar = (fonte: any) => {
    if (!fonte || typeof fonte !== "object" || Array.isArray(fonte)) return;
    for (const [k, v] of Object.entries(fonte)) {
      const chaveNorm = String(k).trim().toLowerCase().replace(/\s+/g, "");
      if (chaveNorm && dadosMesclados[chaveNorm] === undefined && v !== undefined && v !== null) dadosMesclados[chaveNorm] = v;
    }
  };

  const metaBase = carta.metadata ?? carta.data?.metadata;
  const defCarta = metaBase?.customDeck?.cards?.find((c: any) => c.cardId === (metaBase?.cardId ?? carta.cardid ?? carta.name) || c.label === carta.name);

  if (defCarta?.data) incorporar(defCarta.data);
  else { incorporar(carta.data?.data); incorporar(carta.data); incorporar(carta.cardData); incorporar(carta); }

  return dadosMesclados;
}

async function extrairAtributosDaCarta(carta: any) {
  const atributos: Record<string, { rotulo: string; valor: number }> = {};
  const paresBrutos: string[] = [];
  if (!carta) return { atributos, paresBrutos };

  const dados = await obterDadosCustomizadosDaCarta(carta);

  for (let i = 1; i <= 3; i++) {
    const rotulo = String(dados[`atributo${i}`] ?? dados[`atributo_${i}`] ?? "").trim();
    if (!rotulo || ["null", "undefined", "nenhum", "-"].includes(rotulo.toLowerCase())) continue;

    const valorNumerico = Number(String(dados[`valor${i}`] ?? dados[`valor_${i}`] ?? "0").trim().replace(",", "."));
    if (Number.isNaN(valorNumerico) || !Number.isFinite(valorNumerico)) continue;

    paresBrutos.push(`${rotulo}=${valorNumerico}`);
    const chaveAtributo = rotulo.toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "").replace(/\s+/g, " ");

    if (!atributos[chaveAtributo]) atributos[chaveAtributo] = { rotulo, valor: 0 };
    atributos[chaveAtributo].valor += valorNumerico;
  }
  return { atributos, paresBrutos };
}

async function calcularPontuacao(cartaOcorrencia: any, cartasAtaque: any[]): Promise<ResultadoPontuacao> {
  const leituraOcorrencia = await extrairAtributosDaCarta(cartaOcorrencia);
  const somaAcao: Record<string, { rotulo: string; valor: number }> = {};

  for (const cartaAcao of cartasAtaque) {
    const leituraAcao = await extrairAtributosDaCarta(cartaAcao);
    for (const [chave, info] of Object.entries(leituraAcao.atributos)) {
      if (!somaAcao[chave]) somaAcao[chave] = { rotulo: info.rotulo, valor: 0 };
      somaAcao[chave].valor += info.valor;
    }
  }

  let totalRequerido = 0, totalAtendido = 0;
  for (const [chave, infoOcorrencia] of Object.entries(leituraOcorrencia.atributos)) {
    const requerido = Math.max(0, infoOcorrencia.valor);
    if (requerido <= 0) continue;
    const obtido = Math.max(0, somaAcao[chave]?.valor ?? 0);
    totalRequerido += requerido;
    totalAtendido += Math.min(obtido, requerido);
  }

  if (totalRequerido === 0) return { pontos: 0, percentual: 0, passosDebug: [] };
  const proporcao = Math.min(1, totalAtendido / totalRequerido);
  return {
    pontos: Number((proporcao * 10).toFixed(2)),
    percentual: Number((proporcao * 100).toFixed(2)),
    passosDebug: [],
  };
}

// ============================================================================
// 6. MONITORAMENTO CONTÍNUO DA MESA
// ============================================================================

async function iniciarMonitoramentoContinuo() {
  const todosIniciais = await listarTodosObjetos();
  atualizarHistoricoPosicoes(todosIniciais);

  while (estado.faseAtual !== "FIM_DE_JOGO") {
    const pausou = await pausaFisica(0.4);
    if (!pausou) break;

    if (estado.ocupado) continue;
    estado.ocupado = true;
    try {
      if (estado.faseAtual === "FASE_3") {
        await prepararCartasNosSnapPointsDeAtaque();
        const deckAcao = await obterObjetoPorNome("Deck_Acao");
        if (deckAcao && Boolean(deckAcao.faceUp) !== estado.deckAcaoFaceUpBase) {
