            else if (estado.faseAtual === "FASE_4") {
                await verificarConclusaoFase4();
            }
            atualizarHistoricoPosicoes(await listarTodosObjetos());
        }
        finally {
            estado.ocupado = false;
        }
    }
}
iniciarJogo();
